import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    if not isinstance(url, str) or not url:
        raise ValueError("URL must be a non-empty string.")
    if not isinstance(filename, str) or not filename:
        raise ValueError("Filename must be a non-empty string.")

    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    file_path = DOWNLOAD_DIR / filename

    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download from {url}: {e}")

    try:
        with open(file_path, 'wb') as f:
            f.write(response.content)
    except IOError as e:
        raise IOError(f"Failed to save file {filename}: {e}")

    extracted_files = []
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            extracted_files = [str(ZIP_DIR / name) for name in zip_ref.namelist()]
        status = "Extraction successful"
    except zipfile.BadZipFile as e:
        status = "Error: Bad zip file"
    except zipfile.LargeZipFile as e:
        status = "Error: Zip file too large"
    except Exception as e:
        status = "Error: Extraction failed"

    return status, extracted_files

